                if ((string)budgetMode == "budget-state") {
                    if (ceiling.Type != JTokenType.Integer || (long)ceiling < 0 || (long)ceiling > int.MaxValue) { return unavailable; }
                    if ((long)ceiling == 0) {
                        return new JObject(new JProperty("o", "refuse"), new JProperty("r", "refused"), new JProperty("c", "budget_projected"), new JProperty("b", budget), new JProperty("rp", refusedProject), new JProperty("rc", refusedClassification)).ToString(Newtonsoft.Json.Formatting.None);
                    }
                } else if ((string)budgetMode != "token-limits-only" || ceiling.Type != JTokenType.Null) { return unavailable; }
                var ceilingKey = body["personCeilingKey"];
                if (ceilingKey != null && ((string)budgetMode != "budget-state" || ceilingKey.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)ceilingKey, "^[0-9]{4}-(0[1-9]|1[0-2])_[0-9]{1,20}(\\.[0-9]{1,12})?\\z"))) { return unavailable; }
                var decision = new JObject();
                foreach (var field in new string[] { "projectId", "classification", "backendId" }) {
                    var value = body[field];
                    if (value == null || value.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)value, idPattern)) { return unavailable; }
                    decision[field] = (string)value;
                }
