                if (body["restrictedFamiliesApproved"] != null && body["restrictedFamiliesApproved"].Type != JTokenType.Boolean) { return unavailable; }
                var surfaces = body["surfaces"];
                if (surfaces == null ? (string)body["classification"] == "group" : (surfaces.Type != JTokenType.Array || ((JArray)surfaces).Count < 1 || ((JArray)surfaces).Count > 5)) { return unavailable; }
                if (surfaces != null) { var seenSurfaces = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal); foreach (var s in (JArray)surfaces) { if (s.Type != JTokenType.String || Array.IndexOf(new string[] { "chat", "code", "cowork", "design", "m365" }, (string)s) < 0 || !seenSurfaces.Add((string)s)) { return unavailable; } } }
                var chargeback = body["chargebackId"];
                if (chargeback != null && chargeback.Type != JTokenType.Null && (chargeback.Type != JTokenType.String || !System.Text.RegularExpressions.Regex.IsMatch((string)chargeback, "^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}\\z"))) { return unavailable; }
                var familyPolicy = body["familyPolicy"] as JObject;
                if (familyPolicy == null || familyPolicy.Count != 2) { return unavailable; }
                var aggregate = familyPolicy["aggregateLimits"] as JObject;
                var families = familyPolicy["families"] as JObject;
                if (aggregate == null || aggregate.Count != 2 || families == null || families.Count == 0) { return unavailable; }
                var scopes = new System.Collections.Generic.List<JObject>();
                scopes.Add(aggregate["person"] as JObject);
                scopes.Add(aggregate["group"] as JObject);
                var registered = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
                foreach (var family in families.Properties()) {
                    if (Array.IndexOf(new string[] { "haiku", "sonnet", "opus", "fable", "mythos" }, family.Name) < 0) { return unavailable; }
                    if ((family.Name == "fable" || family.Name == "mythos") && !((string)body["classification"] == "CYB" || ((string)body["classification"] == "group" && body["restrictedFamiliesApproved"] != null && body["restrictedFamiliesApproved"].Type == JTokenType.Boolean && (bool)body["restrictedFamiliesApproved"]))) { return unavailable; }
                    var entry = family.Value as JObject;
                    if (entry == null || entry.Count != 3) { return unavailable; }
                    var models = entry["models"] as JArray;
                    if (models == null || models.Count == 0) { return unavailable; }
                    foreach (var model in models) {
