            var models = new System.Collections.Generic.List<string>();
            foreach (var family in ((JObject)JObject.Parse((string)context.Variables["ccofFamilyPolicy"])["families"]).Properties()) {
                if ((family.Name == "fable" || family.Name == "mythos") && classification != "CYB" && !(classification == "group" && context.Variables.GetValueOrDefault<bool>("ccofRestrictedFamiliesApproved", false))) { continue; }
                foreach (var allowed in (JArray)family.Value["models"]) { if (allowed.Type == JTokenType.String) { models.Add((string)allowed); } }
            }
            models.Sort(StringComparer.Ordinal);
            return string.Join(", ", models);
        }

@{
            var enforced = false;
            if (!enforced) { return true; }
            var decision = JObject.Parse((string)context.Variables["ccofDecision"]);
            if ((string)decision["classification"] != "group") { return true; }
            var surfaces = decision["surfaces"] as JArray;
            var surface = (string)context.Variables["ccofSurface"];
            if (surfaces == null || surface == "") { return false; }
            foreach (var s in surfaces) { if (s.Type == JTokenType.String && (string)s == surface) { return true; } }
            return false;
        }

trace.message:
@{
                  var budget = (string)context.Variables["ccofResolverBudgetState"];
                  return new JObject(
                      new JProperty("schemaVersion", 1),
                      new JProperty("requestId", context.RequestId.ToString()),
                      new JProperty("observedAt", DateTime.UtcNow.ToString("o")),
                      new JProperty("resolverOutcome", (string)context.Variables["ccofResolverOutcome"]),
                      new JProperty("resolverDurationMs", (long)context.Variables["ccofResolverMs"]),
                      new JProperty("budgetState", budget == "" ? null : budget),
                      new JProperty("served", false)).ToString(Newtonsoft.Json.Formatting.None);
              }

set-variable.value:
@{
            switch ((string)context.Variables["ccofRefusal"]) {
                case "token_identity_missing": return 401;
                case "token_scope_missing": case "token_client_not_allowed": case "app_token_not_allowed": case "not_authorized": case "model_family_not_allowed": case "surface_not_allowed": return 403;
                case "budget_exhausted": case "budget_projected": case "aggregate_budget_exhausted": return 403;
                case "project_header_invalid": case "request_body_invalid": case "request_model_missing": case "project_selection_required": return 400;
                case "request_content_type": return 415;
                case "request_too_large": return 413;
                default: return 503;
            }
        }

@{
            var code = (string)context.Variables["ccofRefusal"];
            var project = context.Variables.GetValueOrDefault<string>("ccofProjectId", "");
            var classification = context.Variables.GetValueOrDefault<string>("ccofClassification", "");
            var selector = (string)context.Variables["ccofSelector"];
            var model = (string)context.Variables["ccofModel"];
            var scope = classification == "group" ? "group " + project : (project == "" ? "" : "project " + project);
            string type;
            string message;
            switch (code) {
                case "token_identity_missing":
                    type = "authentication_error";
                    message = "The access token has no valid user object id (oid). Sign in to the gateway again.";
                    break;
                case "token_scope_missing":
                    type = "permission_error";
                    message = "The access token does not carry this gateway's access_as_user permission. Sign in again through your organisation's Claude sign-in.";
                    break;
                case "token_client_not_allowed":
                    type = "permission_error";
                    message = "The access token was issued to an application this gateway does not accept. Sign in through your organisation's Claude sign-in.";
                    break;
                case "app_token_not_allowed":
                    type = "permission_error";
                    message = "This gateway accepts a person's sign-in, not an application token. Sign in as yourself.";
                    break;
                case "project_header_invalid":
                    type = "invalid_request_error";
                    message = "The x-ccof-project header must be a project id: a letter or digit followed by up to 79 letters, digits, '_' or '-'.";
                    break;
                case "request_content_type":
                    type = "invalid_request_error";
                    message = "The request body must be JSON, sent with the header Content-Type: application/json.";
                    break;
                case "request_too_large":
                    type = "request_too_large";
                    message = "The request body is larger than 32 MB, the Messages API limit. Send less content, for example fewer or smaller images or documents.";
                    break;
                case "request_body_invalid":
                    type = "invalid_request_error";
                    message = "The request body must be a JSON object.";
                    break;
                case "request_model_missing":
                    type = "invalid_request_error";
                    message = "The request body must name a model in its 'model' field.";
                    break;
                case "not_authorized":
                    type = "permission_error";
                    if (selector == "") {
                        message = "You are not a member of a Claude group on this gateway, or a new membership has not reached it yet (the sync runs every few minutes). Ask your platform team to add you to a Claude group.";
                    } else if (System.Text.RegularExpressions.Regex.IsMatch(selector, "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\z")) {
                        message = "You are not an active member of Claude group " + selector + " on this gateway, or that group is not onboarded. Check the Object ID in the x-ccof-project header, or remove the header to use your default group.";
                    } else {
                        message = "No Claude group or project with ID " + selector + " is available to you. Set the x-ccof-project header to the Object ID of one of your Claude groups (a GUID), not its name or chargeback ID, or remove the header.";
                    }
                    break;
                case "project_selection_required":
                    type = "invalid_request_error";
                    message = "You belong to more than one project. Set the x-ccof-project header to the id of the project this request is for.";
                    break;
                case "budget_exhausted":
                    type = "permission_error";
                    message = "Your Claude budget" + (scope == "" ? "" : " in " + scope) + " is used up for this month. Your access is otherwise unchanged; ask your platform team to raise the budget, or wait for the next month (UTC).";
                    break;
                case "budget_projected":
                    type = "permission_error";
                    message = "Your recent spending" + (scope == "" ? "" : " in " + scope) + " has reached your Claude budget, counting requests not yet recorded. New requests are refused until recorded spend catches up (usually within a few minutes), the budget is raised, or the next month (UTC) starts.";
                    break;
                case "aggregate_budget_exhausted":
                    type = "permission_error";
                    message = (classification == "group" ? "The Claude budget shared by group " + project : "The Claude budget shared by classification " + (classification == "" ? "of your group" : classification) + (project == "" ? "" : " in project " + project)) + " is used up for this month. Your own access is unchanged; ask your platform team to raise the budget, or wait for the next month (UTC).";
                    break;
                case "model_family_not_allowed":
                    type = "permission_error";
                    var allowedModels = context.Variables.GetValueOrDefault<string>("ccofAllowedModels", "");
                    message = (System.Text.RegularExpressions.Regex.IsMatch(model, "^[A-Za-z0-9][A-Za-z0-9._-]{0,119}\\z") ? "Model " + model + " is" : "The requested model is") + " not available" + (scope == "" ? "" : " in " + scope) + "." + (allowedModels == "" ? " Ask your platform team which models your group admits." : " Allowed models: " + allowedModels + ". Choose one of them (in Claude Code: /model), or ask your platform team to admit the model.");
                    break;
                case "surface_not_allowed":
                    var surfaceName = context.Variables.GetValueOrDefault<string>("ccofSurface", "");
                    type = "permission_error";
                    message = "This application" + (surfaceName == "" ? "" : " (" + surfaceName + ")") + " is not enabled for your Claude group. Ask your platform team to enable it, or use an enabled application.";
                    break;
                case "entitlement_unavailable":
                    type = "api_error";
                    message = "The gateway could not confirm your access just now. This is not a problem with your access. Retry in 5 seconds.";
                    break;
                case "backend_credential_unavailable":
                    type = "api_error";
                    message = "The gateway could not get a credential for the model service. Your access is unaffected. Retry in 5 seconds; if this continues, tell your platform team.";
                    break;
                case "budget_state_unavailable":
                    type = "api_error";
                    message = "The budget state for your project could not be confirmed, so this request cannot be admitted now. This is not about your access. Retry in 5 seconds; if this continues, tell your platform team.";
                    break;
                case "backend_not_configured":
                    type = "api_error";
                    message = "The model service for project " + project + " is not configured on this gateway. Your access is unaffected; tell your platform team.";
                    break;
                default:
                    type = "api_error";
                    message = "The gateway refused the request.";
                    break;
            }
            return new JObject(
                new JProperty("type", "error"),
                new JProperty("error", new JObject(
                    new JProperty("type", type),
                    new JProperty("message", message + " Request id: " + context.RequestId.ToString() + ".")))).ToString(Newtonsoft.Json.Formatting.None);
        }

set-status.reason:
@{
                  switch ((int)context.Variables["ccofRefusalStatus"]) {
                      case 400: return "Bad Request";
                      case 401: return "Unauthorized";
                      case 403: return "Forbidden";
                      case 413: return "Content Too Large";
                      case 415: return "Unsupported Media Type";
                      default: return "Service Unavailable";
                  }
              }

